import { describe, expect, it, vi, beforeEach } from 'vitest';
import * as repo from './repo.js';

vi.mock('./repo.js', () => ({
  appendChangeLog: vi.fn(),
  listChangeLog: vi.fn(),
  getChangeLogEntry: vi.fn(),
}));

describe('appendChangeLog', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it('does not include an id key in the insert payload', async () => {
    const entry = {
      Who: 'test-user',
      Action: 'create' as const,
      Collection: 'characters',
      ObjectId: 'ch-1',
      ObjectName: 'Test Character',
      Before: null,
      After: { name: 'Updated' },
    } as const;

    await repo.appendChangeLog(entry);

    const calls = (vi.mocked(repo.appendChangeLog) as unknown as ReturnType<typeof vi.fn>).mock.calls;
    expect(calls.length).toBe(1);
    const payload = calls[0][0];
    expect(payload).not.toHaveProperty('id');
  });

  it('includes exactly the changelog table columns in snake_case', async () => {
    const entry = {
      Who: 'test-user',
      Action: 'create' as const,
      Collection: 'characters',
      ObjectId: 'ch-1',
      ObjectName: 'Test Character',
      Before: null,
      After: { name: 'Updated' },
    } as const;

    await repo.appendChangeLog(entry);

    const calls = (vi.mocked(repo.appendChangeLog) as unknown as ReturnType<typeof vi.fn>).mock.calls;
    expect(calls.length).toBe(1);
    const payload = calls[0][0];
    expect(payload).toHaveProperty('at');
    expect(payload).toHaveProperty('who');
    expect(payload).toHaveProperty('action');
    expect(payload).toHaveProperty('collection');
    expect(payload).toHaveProperty('object_id');
    expect(payload).toHaveProperty('object_name');
    expect(payload).toHaveProperty('before');
    expect(payload).toHaveProperty('after');
    expect(Object.keys(payload)).toHaveLength(6);
    expect((payload as any).who).toBe('test-user');
    expect((payload as any).action).toBe('create');
    expect((payload as any).collection).toBe('characters');
    expect((payload as any).object_id).toBe('ch-1');
    expect((payload as any).object_name).toBe('Test Character');
    expect((payload as any).before).toBeNull();
    expect((payload as any).after).toEqual({ name: 'Updated' });
  });

  it('propagates errors from the mocked insert call', async () => {
    const error = new Error('insert rejected');
    const mockAppend = vi.mocked(repo.appendChangeLog) as ReturnType<typeof vi.fn>;
    mockAppend.mockRejectedValueOnce(error);

    try {
      await repo.appendChangeLog({
        Who: 'test-user',
        Action: 'create' as const,
        Collection: 'characters',
        ObjectId: 'ch-1',
        ObjectName: 'Test Character',
        Before: null,
        After: null,
      } as const);
      expect(true).toBe(false); // should not reach here
    } catch (e) {
      expect(e).toBe(error);
    }
  });
});

