import { describe, expect, it, vi, beforeEach } from 'vitest';
import { supabaseAdmin } from './supabase.js';
import * as repo from './repo.js';

vi.mock('./supabase.js', () => ({
  supabaseAdmin: {
    from: vi.fn().mockReturnValue({
      insert: vi.fn().mockResolvedValue({ data: {}, error: null }),
    }),
  },
}));

describe('appendChangeLog', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it('does not include an id key in the insert payload', async () => {
    const entry = {
      Who: 'test-user',
      Action: 'create' as const,
      Collection: 'characters',
      ObjectId: 'ch-1',
      ObjectName: 'Test Character',
      Before: null,
      After: { name: 'Updated' },
    } as const;

    await repo.appendChangeLog(entry);

    const insertCalls = vi.mocked(supabaseAdmin.from).mock.calls;
    expect(insertCalls.length).toBe(1);
    const payload = insertCalls[0][0];
    expect(payload).not.toHaveProperty('id');
  });

  it('includes exactly the changelog table columns in snake_case', async () => {
    const entry = {
      Who: 'test-user',
      Action: 'create' as const,
      Collection: 'characters',
      ObjectId: 'ch-1',
      ObjectName: 'Test Character',
      Before: null,
      After: { name: 'Updated' },
    } as const;

    await repo.appendChangeLog(entry);

    const insertCalls = vi.mocked(supabaseAdmin.from).mock.calls;
    expect(insertCalls.length).toBe(1);
    const payload = insertCalls[0][0];
    expect(payload).toHaveProperty('at');
    expect(payload).toHaveProperty('who');
    expect(payload).toHaveProperty('action');
    expect(payload).toHaveProperty('collection');
    expect(payload).toHaveProperty('object_id');
    expect(payload).toHaveProperty('object_name');
    expect(payload).toHaveProperty('before');
    expect(payload).toHaveProperty('after');
    expect(Object.keys(payload)).toHaveLength(7);
    expect(payload.who).toBe('test-user');
    expect(payload.action).toBe('create');
    expect(payload.collection).toBe('characters');
    expect(payload.object_id).toBe('ch-1');
    expect(payload.object_name).toBe('Test Character');
    expect(payload.before).toBeNull();
    expect(payload.after).toEqual({ name: 'Updated' });
  });

  it('propagates errors from the mocked insert call', async () => {
    const error = new Error('insert rejected');
    vi.mocked(supabaseAdmin.from).mockReturnValue({
      insert: vi.fn().mockRejectedValueOnce(error),
    } as any);

    try {
      await repo.appendChangeLog({
        Who: 'test-user',
        Action: 'create' as const,
        Collection: 'characters',
        ObjectId: 'ch-1',
        ObjectName: 'Test Character',
        Before: null,
        After: null,
      } as const);
      expect(true).toBe(false); // should not reach here
    } catch (e) {
      expect(e).toBe(error);
    }
  });
});

